// Mobile attendance admin view
async function loadAttendance(date=today()){
  view.innerHTML='<div class="loading">Memuat…</div>';
  const rows=await call('listAttendance',{date});
  await renderAttendance(rows,date);
}
function sameYmd(v,date){return !date || String(v||'').slice(0,10)===date}
function sessionMatchesDate(x,date){return !date || sameYmd(x.check_in_at,date) || sameYmd(x.check_out_at,date) || sameYmd(x.created_at,date)}
function employeeAttendanceStatus(emp,sessions,date){
  const sess=sessions.find(s=>s.employee_id===emp.id && sessionMatchesDate(s,date));
  if(!sess) return {status:'absent',label:'Belum absen',icon:'⚪',time:''};
  if(sess.status==='ACTIVE') return {status:'active',label:'Sedang absen',icon:'🟢',time:`Masuk ${fmtTime(sess.check_in_at)}`};
  if(sess.check_out_at) return {status:'done',label:'Sudah pulang',icon:'🏠',time:`Masuk ${fmtTime(sess.check_in_at)} · Pulang ${fmtTime(sess.check_out_at)}`};
  return {status:'checkedin',label:'Sudah masuk',icon:'✅',time:`Masuk ${fmtTime(sess.check_in_at)}`};
}
function fmtTime(t){if(!t)return'-';try{return new Date(t).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}catch{return'-'}}
async function renderAttendance(rows,date=today()){
  const live=await call('attendanceLive');
  const history=(await call('attendanceHistory',{date})).filter(x=>sessionMatchesDate(x,date));
  const locLog=(await call('attendanceLocationLog',{date})).filter(x=>sameYmd(x.recorded_at,date) || sameYmd(x.created_at,date)).sort((a,b)=>String(b.recorded_at||b.created_at).localeCompare(String(a.recorded_at||a.created_at)));
  const allEmployees=await call('listEmployees');
  const activeEmployees=allEmployees.filter(e=>e.active);
  head('Absensi Karyawan','Live lokasi & riwayat absensi mobile','Refresh',()=>loadAttendance(document.getElementById('attendanceDate')?.value||today()));
  const employeeStatusList=activeEmployees.map(emp=>{
    const st=employeeAttendanceStatus(emp,history,date);
    return `<div class="emp-status-item ${st.status}"><div class="emp-initial">${esc(emp.name?.slice(0,1)||'K')}</div><div class="emp-info"><div class="emp-name">${esc(emp.name)}</div><div class="emp-status-label"><span class="status-icon">${st.icon}</span>${esc(st.label)}<span class="status-time">${esc(st.time)}</span></div></div></div>`;
  }).join('');
  view.innerHTML=`<div class="attendance-page"><div class="card attendance-filter"><div><h2>Filter Absensi</h2><p>Pilih tanggal untuk melihat log, riwayat sesi, dan push lokasi.</p></div><label>Tanggal<input id="attendanceDate" type="date" value="${esc(date)}" onchange="loadAttendance(this.value)"></label><button class="btn" onclick="loadAttendance(document.getElementById('attendanceDate').value)">Terapkan</button><button class="btn secondary" onclick="loadAttendance(today())">Hari Ini</button></div><div class="grid cards">${metric('Sedang Aktif',live.length+' orang')}${metric('Log Tanggal Ini',(rows||[]).length+' event')}${metric('Total Sesi',history.length+' sesi')}${metric('Push Lokasi',locLog.length+' log')}</div><div class="card"><div class="section-head"><h2>Status Karyawan Hari Ini</h2><span class="badge">${esc(date)}</span></div><div class="emp-status-grid">${employeeStatusList||'<div class="empty">Tidak ada karyawan aktif.</div>'}</div></div><div class="grid two"><div class="card"><div class="section-head"><h2>Live Lokasi</h2><span class="badge">aktif sekarang</span></div>${attendanceLiveTable(live)}</div><div class="card"><div class="section-head"><h2>Log Absensi</h2><span class="badge">${esc(date)}</span></div>${attendanceLogTable(rows||[])}</div></div><div class="card"><div class="section-head"><h2>Riwayat Sesi</h2><button class="link" onclick="go('employees')">Kelola PIN</button></div>${attendanceHistoryTable(history)}</div><div class="card"><div class="section-head"><div><h2>Realtime Push Lokasi</h2><small id="attendanceAutoRefreshLabel">Auto-refresh aktif saat halaman ini dibuka.</small></div><span class="badge">${esc(date)} · tiap ±30 detik / 25m</span></div><div id="attendanceLocationPushWrap">${attendanceLocationPushTable(locLog)}</div></div></div>`;
  startAttendanceCountdown();
  startAttendanceAutoRefresh(date);
}
function pingAge(t){const str=(t||'').trim();const d=new Date(str.includes('T')?str:str.replace(' ','T'));return isFinite(d.getTime())?Math.max(0,Math.round((Date.now()-d.getTime())/1000)):999999}
function pingLabel(t){const s=pingAge(t);if(s<90)return 'baru saja';if(s<3600)return Math.round(s/60)+' menit lalu';return Math.round(s/3600)+' jam lalu'}
function mapsLink(lat,lng){return lat&&lng?`<a class="link" target="_blank" href="https://www.google.com/maps?q=${lat},${lng}">Map</a>`:'-'}
function attendanceLiveTable(d){return d.length?`<div class="table-wrap"><table><thead><tr><th>Karyawan</th><th>Status</th><th>Last Ping</th><th>Next Push</th><th>Accuracy</th><th>Lokasi</th><th>Foto Masuk</th></tr></thead><tbody>${d.map(x=>`<tr data-last-ping="${esc(x.last_ping_at)}"><td><b>${esc(x.employee_name)}</b><small>${esc(x.employee_id)}</small></td><td>${badge(pingAge(x.last_ping_at)>180?'LOST':'LIVE')}</td><td>${pingLabel(x.last_ping_at)}</td><td class="countdown-cell">-</td><td>${x.last_accuracy?Math.round(x.last_accuracy)+' m':'-'}</td><td>${mapsLink(x.last_lat,x.last_lng)}</td><td>${x.check_in_photo_url?`<a class="link" target="_blank" href="${esc(x.check_in_photo_url)}">Lihat</a>`:'-'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Tidak ada karyawan aktif.</div>'}
function attendanceLogTable(d){return d.length?`<div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Karyawan</th><th>Tipe</th><th>Lokasi</th><th>Foto</th></tr></thead><tbody>${d.map(x=>`<tr><td>${esc(x.time||'')}</td><td>${esc(x.employee_name||'-')}</td><td>${badge(x.type||'-')}</td><td>${mapsLink(x.lat,x.lng)}</td><td>${x.photo_url?`<a class="link" target="_blank" href="${esc(x.photo_url)}">Lihat</a>`:'-'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada log hari ini.</div>'}
function attendanceLocationPushTable(d){return d.length?`<div class="table-wrap"><table><thead><tr><th>Waktu Push</th><th>Session</th><th>Karyawan</th><th>Accuracy</th><th>Lokasi</th><th>Diterima Server</th></tr></thead><tbody>${d.map(x=>`<tr><td><b>${formatDateTime(x.recorded_at)}</b><small>${pingLabel(x.recorded_at)}</small></td><td>${esc(x.session_id||'-')}</td><td><b>${esc(x.employee_name||x.employee_id||'-')}</b><small>${esc(x.employee_id||'')}</small></td><td>${x.accuracy?Math.round(x.accuracy)+' m':'-'}</td><td>${mapsLink(x.lat,x.lng)}</td><td>${formatDateTime(x.created_at)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada push lokasi. Log muncul setelah app aktif absen dan mengirim GPS.</div>'}
function attendanceHistoryTable(d){return d.length?`<div class="table-wrap"><table><thead><tr><th>Karyawan</th><th>Masuk</th><th>Pulang</th><th>Status</th><th>Last Ping</th><th>Lokasi</th><th>Foto</th></tr></thead><tbody>${d.map(x=>`<tr><td><b>${esc(x.employee_name)}</b><small>${esc(x.employee_id)}</small></td><td>${formatDateTime(x.check_in_at)}</td><td>${x.check_out_at?formatDateTime(x.check_out_at):'-'}</td><td>${badge(x.status)}</td><td>${pingLabel(x.last_ping_at)}</td><td>${mapsLink(x.last_lat,x.last_lng)}</td><td>${x.check_in_photo_url?`<a class="link" target="_blank" href="${esc(x.check_in_photo_url)}">Masuk</a>`:''} ${x.check_out_photo_url?`<a class="link" target="_blank" href="${esc(x.check_out_photo_url)}">Pulang</a>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada sesi absensi.</div>'}

// Countdown + auto-refresh lokasi admin
let attendanceCountdownTimer=null, attendanceAutoRefreshTimer=null, attendanceLastPushKey='';
function stopAttendanceTimers(){ if(attendanceCountdownTimer){clearInterval(attendanceCountdownTimer);attendanceCountdownTimer=null} if(attendanceAutoRefreshTimer){clearInterval(attendanceAutoRefreshTimer);attendanceAutoRefreshTimer=null} }
function startAttendanceCountdown() {
  if(attendanceCountdownTimer) clearInterval(attendanceCountdownTimer);
  attendanceCountdownTimer=setInterval(() => {
    document.querySelectorAll('.countdown-cell').forEach(cell => {
      const row = cell.closest('tr');
      const lastPing = row?.dataset.lastPing;
      if (!lastPing) return;
      const elapsed = Math.floor((Date.now() - new Date(lastPing.replace(' ','T')).getTime()) / 1000);
      const remaining = Math.max(0, 30 - elapsed);
      cell.textContent = remaining > 0 ? `${remaining}s` : 'pushing...';
      if (remaining === 0) cell.style.fontWeight = '900';
    });
  }, 1000);
}
async function refreshAttendancePushLog(date){
  const wrap=document.getElementById('attendanceLocationPushWrap'); if(!wrap) return stopAttendanceTimers();
  const locLog=(await call('attendanceLocationLog',{date})).filter(x=>sameYmd(x.recorded_at,date)||sameYmd(x.created_at,date)).sort((a,b)=>String(b.recorded_at||b.created_at).localeCompare(String(a.recorded_at||a.created_at)));
  const key=locLog[0] ? `${locLog[0].id||''}-${locLog[0].recorded_at||locLog[0].created_at}` : '';
  if(key!==attendanceLastPushKey){ attendanceLastPushKey=key; wrap.innerHTML=attendanceLocationPushTable(locLog); }
  const label=document.getElementById('attendanceAutoRefreshLabel'); if(label) label.textContent=`Auto-refresh aktif · update ${new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`;
}
function startAttendanceAutoRefresh(date){
  if(attendanceAutoRefreshTimer) clearInterval(attendanceAutoRefreshTimer);
  refreshAttendancePushLog(date);
  attendanceAutoRefreshTimer=setInterval(()=>refreshAttendancePushLog(date),5000);
}
if (typeof window !== 'undefined') {
  document.addEventListener('DOMContentLoaded', () => startAttendanceCountdown());
}

// Close multiselect dropdown when clicking outside
document.addEventListener('click', function(e) {
  if (!e.target.closest('.modern-multiselect')) {
    document.querySelectorAll('.multiselect-dropdown').forEach(dd => dd.classList.remove('show'));
  }
});
